package uk.buzzlab;
import android.content.Context; import android.graphics.*; import android.os.*; import android.view.*; import java.io.*; import java.net.*; import java.util.*; import java.util.concurrent.*;
/** OpenStreetMap tiles, darkened, with routes coloured by speed. Drag to move, pinch to zoom, double-tap to fit. */
final class MapView extends View {
  static final ExecutorService NET=Executors.newFixedThreadPool(2); static final Map<String,Bitmap> MEM=Collections.synchronizedMap(new LinkedHashMap<String,Bitmap>(64,.75f,true){ protected boolean removeEldestEntry(Map.Entry<String,Bitmap> e){ return size()>120; } }); static final Set<String> BUSY=Collections.synchronizedSet(new HashSet<>());
  final List<Trip> trips=new ArrayList<>(); final File cache; final float D; double cx,cy,scale=1; int z=12; boolean fitted; final Paint tp=new Paint(Paint.FILTER_BITMAP_FLAG), lp=new Paint(Paint.ANTI_ALIAS_FLAG), tx=new Paint(Paint.ANTI_ALIAS_FLAG); final ScaleGestureDetector sg; final GestureDetector gd; float lx,ly; final Handler h=new Handler(Looper.getMainLooper()); final int bg;
  MapView(Context c,List<Trip> t,int bg){ super(c); this.bg=bg; for(Trip x:t)if(x.lat.length>1)trips.add(x); cache=new File(c.getCacheDir(),"tiles"); D=getResources().getDisplayMetrics().density;
    ColorMatrix m=new ColorMatrix(new float[]{-.75f,0,0,0,190, 0,-.75f,0,0,195, 0,0,-.7f,0,205, 0,0,0,1,0}); ColorMatrix s=new ColorMatrix(); s.setSaturation(.25f); m.postConcat(s); tp.setColorFilter(new ColorMatrixColorFilter(m));
    lp.setStyle(Paint.Style.STROKE); lp.setStrokeCap(Paint.Cap.ROUND); lp.setStrokeWidth(4*D); tx.setTextSize(10*D); tx.setColor(0xCCF2F0EA);
    sg=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){ public boolean onScale(ScaleGestureDetector d){ zoomAt(d.getScaleFactor(),d.getFocusX(),d.getFocusY()); return true; } });
    gd=new GestureDetector(c,new GestureDetector.SimpleOnGestureListener(){ public boolean onDoubleTap(MotionEvent e){ fitted=false; invalidate(); return true; } }); }
  static double mx(double lon,int z){ return (lon+180)/360*256*(1<<z); } static double my(double lat,int z){ double r=Math.toRadians(lat); return (1-Math.log(Math.tan(r)+1/Math.cos(r))/Math.PI)/2*256*(1<<z); }
  protected void onMeasure(int w,int hh){ int W=MeasureSpec.getSize(w); setMeasuredDimension(W,(int)(W*.8)); }
  void fit(){ if(trips.isEmpty()||getWidth()==0)return; double a=90,b=-90,c=180,d=-180; for(Trip t:trips)for(int i=0;i<t.lat.length;i++){ a=Math.min(a,t.lat[i]); b=Math.max(b,t.lat[i]); c=Math.min(c,t.lon[i]); d=Math.max(d,t.lon[i]); } z=17; while(z>2&&(mx(d,z)-mx(c,z)>getWidth()*.86||my(a,z)-my(b,z)>getHeight()*.82))z--; cx=(mx(c,z)+mx(d,z))/2; cy=(my(a,z)+my(b,z))/2; scale=1; fitted=true; }
  void zoomAt(float f,float fx,float fy){ double wx=cx+(fx-getWidth()/2.0)/scale, wy=cy+(fy-getHeight()/2.0)/scale; scale*=f; while(scale>1.6&&z<18){ scale/=2; z++; wx*=2; wy*=2; } while(scale<.8&&z>2){ scale*=2; z--; wx/=2; wy/=2; } cx=wx-(fx-getWidth()/2.0)/scale; cy=wy-(fy-getHeight()/2.0)/scale; invalidate(); }
  public boolean onTouchEvent(MotionEvent e){ getParent().requestDisallowInterceptTouchEvent(true); gd.onTouchEvent(e); sg.onTouchEvent(e); if(e.getPointerCount()==1&&!sg.isInProgress()){ if(e.getActionMasked()==MotionEvent.ACTION_MOVE){ cx-=(e.getX()-lx)/scale; cy-=(e.getY()-ly)/scale; invalidate(); } lx=e.getX(); ly=e.getY(); } else if(e.getPointerCount()>1){ lx=e.getX(0); ly=e.getY(0); } if(e.getActionMasked()==MotionEvent.ACTION_UP)getParent().requestDisallowInterceptTouchEvent(false); return true; }
  /** Cool blue when slow, through teal and yellow, to hot orange and red when fast. */
  static int speedColour(double v){ int[] c={0xFF3F7FE0,0xFF2EC4B6,0xFFFFD166,0xFFFF8A3D,0xFFFF3B1F}; double[] at={0,20,40,55,70}; if(v!=v)return 0xFF7C8B95; if(v<=0)return c[0]; for(int i=1;i<at.length;i++)if(v<at[i]){ double w=(v-at[i-1])/(at[i]-at[i-1]); int a=c[i-1],b=c[i],o=0xFF000000; for(int s=0;s<24;s+=8)o|=((int)Math.round(((a>>s)&255)*(1-w)+((b>>s)&255)*w))<<s; return o; } return c[c.length-1]; }
  protected void onDraw(Canvas g){ if(!fitted)fit(); g.drawColor(bg); float W=getWidth(),H=getHeight(); double ts=256*scale; double left=cx-W/2/scale, top=cy-H/2/scale; int n=1<<z;
    for(int tx0=(int)Math.floor(left/256);tx0<=Math.floor((cx+W/2/scale)/256);tx0++)for(int ty=(int)Math.floor(top/256);ty<=Math.floor((cy+H/2/scale)/256);ty++){ if(ty<0||ty>=n)continue; int tx1=((tx0%n)+n)%n; Bitmap b=tile(z,tx1,ty); if(b!=null)g.drawBitmap(b,null,new RectF((float)((tx0*256-left)*scale),(float)((ty*256-top)*scale),(float)((tx0*256-left)*scale+ts),(float)((ty*256-top)*scale+ts)),tp); }
    lp.setStrokeWidth((trips.size()>3?3:4.5f)*D); for(Trip t:trips){ float px=0,py=0; for(int i=0;i<t.lat.length;i++){ float x=(float)((mx(t.lon[i],z)-left)*scale),y=(float)((my(t.lat[i],z)-top)*scale); if(i>0&&t.t[i]-t.t[i-1]<6){ lp.setColor(speedColour(t.mph[i])); g.drawLine(px,py,x,y,lp); } px=x; py=y; } }
    String a="© OpenStreetMap contributors"; float aw=tx.measureText(a); Paint bgp=new Paint(); bgp.setColor(0x99021B29); g.drawRect(W-aw-10*D,H-16*D,W,H,bgp); g.drawText(a,W-aw-5*D,H-5*D,tx); if(trips.isEmpty()){ tx.setTextSize(14*D); g.drawText("No positions recorded",16*D,30*D,tx); tx.setTextSize(10*D); } }
  Bitmap tile(int z,int x,int y){ final String k=z+"/"+x+"/"+y; Bitmap b=MEM.get(k); if(b!=null)return b; final File f=new File(cache,k+".png"); if(BUSY.add(k)) NET.execute(()->{ try{ Bitmap got=null; if(f.exists()&&System.currentTimeMillis()-f.lastModified()<30L*86400000)got=BitmapFactory.decodeFile(f.getPath()); if(got==null){ HttpURLConnection c=(HttpURLConnection)new URL("https://tile.openstreetmap.org/"+k+".png").openConnection(); c.setRequestProperty("User-Agent","BuzzLab/2.5 (personal Android app)"); c.setConnectTimeout(10000); c.setReadTimeout(15000); if(c.getResponseCode()==200){ ByteArrayOutputStream o=new ByteArrayOutputStream(); try(InputStream in=c.getInputStream()){ byte[] q=new byte[16384]; int n; while((n=in.read(q))>0)o.write(q,0,n); } byte[] d=o.toByteArray(); got=BitmapFactory.decodeByteArray(d,0,d.length); if(got!=null){ f.getParentFile().mkdirs(); try(FileOutputStream w=new FileOutputStream(f)){ w.write(d); } } } c.disconnect(); } if(got!=null){ MEM.put(k,got); h.post(this::invalidate); } }catch(Exception e){} finally{ BUSY.remove(k); } }); return null; }
}
